$file=dirname(__DIR__).'/data/fontes.json'; function read_fontes($f){ if(!file_exists($f)) return []; $d=json_decode(file_get_contents($f),true); return is_array($d)?$d:[]; } function save_fontes($f,$d){ file_put_contents($f,json_encode(array_values($d),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),LOCK_EX); }
$fontes=read_fontes($file); $msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){ $action=$_POST['action']??''; $idx=(int)($_POST['idx']??-1); if($action==='add'){ $fontes[]=['type'=>trim($_POST['type']??'Oficial'),'city'=>trim($_POST['city']??'Região'),'name'=>trim($_POST['name']??''),'url'=>trim($_POST['url']??''),'rss'=>trim($_POST['rss']??''),'active'=>!empty($_POST['active'])]; save_fontes($file,$fontes); header('Location: fontes.php?ok=1'); exit; } if($action==='delete' && isset($fontes[$idx])){ array_splice($fontes,$idx,1); save_fontes($file,$fontes); header('Location: fontes.php?del=1'); exit; } }
